const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const settings = settingsOf('Load settings');
const messages = $('When called').all().map((item, index) => {
  const m = item.json || {};
  const text = (m.text || '').toString();
  if (!m.card && !text.trim()) return { index, note: 'empty message' };
  if (!m.reply_to && !settings.lark_chat_id && !settings.lark_open_id) return { index, note: 'not delivered: nobody has linked the Lark bot yet' };
  const msg_type = m.card ? 'interactive' : 'text';
  const content = JSON.stringify(m.card ? m.card : { text: text.slice(0, 20000) });
  return {
    index,
    deliver: true,
    url: m.reply_to
      ? `https://open.larksuite.com/open-apis/im/v1/messages/${m.reply_to}/reply`
      : `https://open.larksuite.com/open-apis/im/v1/messages?receive_id_type=${settings.lark_chat_id ? 'chat_id' : 'open_id'}`,
    body: m.reply_to
      ? { msg_type, content, reply_in_thread: true }
      : { receive_id: settings.lark_chat_id || settings.lark_open_id, msg_type, content },
  };
});
return [{ json: { messages, any: messages.some((m) => m.deliver) } }];

const token = $json.tenant_access_token;
if (!token) throw new Error('No Lark tenant token: ' + JSON.stringify($json).slice(0, 300));
return $('Build messages').first().json.messages.filter((m) => m.deliver).map((m) => ({ json: { ...m, token } }));

// Lark answers HTTP 200 with a non-zero code on some errors.
const requests = $('Requests').all();
const sent = {};
$input.all().forEach((item, i) => {
  const r = item.json || {};
  if (r.code !== 0) throw new Error(`Lark send failed: ${r.code} ${r.msg}`);
  sent[requests[i].json.index] = r.data.message_id;
});
return $('Build messages').first().json.messages.map((m) => ({
  json: { message_id: sent[m.index] || null, delivered: Boolean(sent[m.index]), note: m.note || '' },
}));
